package cn.binbin.crm;
import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.support.TransactionTemplate;import static cn.binbin.crm.TradeService.*;
@RestController @RequestMapping("/api/v1")
public class PilotController {
 public record Plan(boolean automationEnabled,@Min(0) @Max(1000) int automationRuleLimit,@Min(0) @Max(1000000) int automationMonthlyLimit,boolean workspaceEnabled,@Min(0) @Max(1000) int publicFormLimit,@Min(0) @Max(1000000) int publicSubmissionMonthlyLimit,boolean migrationEnabled,@Min(0) @Max(1000000) int migrationMonthlyRowLimit,@Min(0) long expectedVersion){}
 private final AuthService auth;private final PilotService pilot;private final P3Base b;
 public PilotController(AuthService auth,PilotService pilot,P3Base b){this.auth=auth;this.pilot=pilot;this.b=b;}
 private AuthService.Session write(HttpServletRequest r){var s=auth.workspace(r);auth.csrf(s,r);return s;}
 @GetMapping("/pilot/readiness") public Object readiness(HttpServletRequest r){return pilot.readiness(auth.workspace(r));}
 @GetMapping("/pilot/history") public Object history(HttpServletRequest r){return pilot.history(auth.workspace(r));}
 @PostMapping("/pilot/checks") public Object record(@Valid @RequestBody PilotService.Record i,HttpServletRequest r){return pilot.record(write(r),i,RequestSafety.trace(r));}
 @GetMapping("/platform/p7/plans") public Object plans(HttpServletRequest r){auth.platform(auth.workspace(r));return map("items",b.rows("SELECT id,code,name,version,automation_enabled,automation_rule_limit,automation_monthly_limit,workspace_enabled,public_form_limit,public_submission_monthly_limit,migration_enabled,migration_monthly_row_limit FROM sys_plan ORDER BY code",Map.of()));}
 @PutMapping("/platform/p7/plans/{id}") public Object plan(@PathVariable UUID id,@Valid @RequestBody Plan i,HttpServletRequest r){var s=write(r);auth.platform(s);return b.tx.execute(st->{int n=b.db.update("UPDATE sys_plan SET automation_enabled=:automation,automation_rule_limit=:rules,automation_monthly_limit=:runs,workspace_enabled=:workspace,public_form_limit=:forms,public_submission_monthly_limit=:submissions,migration_enabled=:migration,migration_monthly_row_limit=:rows,version=version+1 WHERE id=:id AND version=:version",map("id",id,"version",i.expectedVersion(),"automation",i.automationEnabled(),"rules",i.automationRuleLimit(),"runs",i.automationMonthlyLimit(),"workspace",i.workspaceEnabled(),"forms",i.publicFormLimit(),"submissions",i.publicSubmissionMonthlyLimit(),"migration",i.migrationEnabled(),"rows",i.migrationMonthlyRowLimit()));if(n!=1)throw ApiError.conflict("套餐已变化，请刷新");b.db.update("INSERT INTO sys_platform_audit(id,actor_user_id,action,target_id,details,trace_id) VALUES(:event,:actor,'P7_PLAN_UPDATED',:id,cast(:details AS jsonb),:trace)",map("event",UUID.randomUUID(),"actor",s.userId(),"id",id,"details",b.json(i),"trace",RequestSafety.trace(r)));return plans(r);});}
}
